 let missionFilter='all',rewardTimer;
 let state=R.empty(),revision=0,definitions=clone(window.KizunaAdventureSeed),owner=null,epoch=0,loading=false,busy=false,error='',view='constellations',selection='',filter='',query='',offset=0,publicRows=[],hasMorePublic=false,publicBusy=false,publicError='',clockOffset=0,loaded=false,zoom=1,pan={x:0,y:0},pendingRender=false;
