 async function visit(key){const a=window.KizunaGame.getAlbums().find(a=>a.key===key||a.name===key);if(!a||!ready())return;const previous=Number(state.visits[a.name]||0);if(new Date(previous).toISOString().slice(0,10)===new Date(now()).toISOString().slice(0,10))return;await mutate('visit',{universe:a.name});}
