 async function openPublic(id){const token=epoch;try{const rows=await publicRead('kizuna_sanctuaries','select=user_id,username,presentation&is_public=eq.true&user_id=eq.'+encodeURIComponent(id)+'&limit=1');if(token!==epoch)return;const p=rows[0];if(!p){notice('Ce Sanctuaire est privé ou n’est plus disponible.');directory();return;}openDialog('Sanctuaire de '+p.username,sanctuaryMarkup(p.presentation.settings,p.username,p.presentation.badges,p.presentation.awakened,p.presentation.constellations));}catch(err){notice(friendly(err));}}
